'EPIC-005'; from datetime import date; from decimal import Decimal; import pytest; from httpx import AsyncClient; from pydantic import ValidationError; from sqlalchemy.ext.asyncio import AsyncSession; from src.ledger import Account, AccountType, Direction, JournalEntry, JournalEntryStatus, JournalLine; from src.reporting.extension.reporting_calc import AnnualizedIncomeTotals, resolve_line_currency; from src.schemas.base import normalize_currency_code; from src.schemas.income import AnnualizedIncomeResponse, FxConversionErrorResponse
def test_AC5_32_1_currency_code_type_validates_and_normalizes():
    'AC-reporting.income-typed.1 AC5.32.1'; field = AnnualizedIncomeResponse.model_fields['currency']; assert field.annotation is str; assert any((getattr(m, 'min_length', None) == 3 for m in field.metadata)); assert any((getattr(m, 'max_length', None) == 3 for m in field.metadata)); assert any((getattr(m, 'func', None) is normalize_currency_code for m in field.metadata)); response = AnnualizedIncomeResponse(annualized_salary=Decimal('1.00'), annualized_bonus=Decimal('0.00'), annualized_dividend=Decimal('0.00'), annualized_total=Decimal('1.00'), currency=' sgd ', as_of=date(2026, 5, 20)); assert response.currency == 'SGD'
    with pytest.raises(ValidationError): AnnualizedIncomeResponse(annualized_salary=Decimal('1.00'), annualized_bonus=Decimal('0.00'), annualized_dividend=Decimal('0.00'), annualized_total=Decimal('1.00'), currency='SGDX', as_of=date(2026, 5, 20))
def test_AC5_32_2_annualized_income_totals_is_typed_intermediate():
    'AC-reporting.income-typed.2 AC5.32.2'; totals = AnnualizedIncomeTotals(); assert (totals.salary, totals.bonus, totals.dividend, totals.total) == (Decimal('0.00'), Decimal('0.00'), Decimal('0.00'), Decimal('0.00')); totals.add('salary', Decimal('120000.00')); totals.add('bonus', Decimal('15000.00')); totals.add(None, Decimal('300.00')); assert totals.salary == Decimal('120000.00'); assert totals.bonus == Decimal('15000.00'); assert totals.dividend == Decimal('0.00'); assert totals.total == Decimal('135300.00'); assert all((isinstance(v, Decimal) for v in (totals.salary, totals.bonus, totals.dividend, totals.total)))
    with pytest.raises(ValueError, match='Unknown income bucket'): totals.add('total', Decimal('1.00'))
    with pytest.raises(ValueError, match='Unknown income bucket'): totals.add('not_a_bucket', Decimal('1.00'))
    assert totals.total == Decimal('135300.00')
def test_AC5_32_3_resolve_line_currency_uses_canonical_fallback_chain(): 'AC-reporting.income-typed.3 AC5.32.3'; account = Account(name='Salary', type=AccountType.INCOME, currency='usd'); line_with_currency = JournalLine(direction=Direction.CREDIT, amount=Decimal('1.00'), currency='eur'); line_no_currency = JournalLine(direction=Direction.CREDIT, amount=Decimal('1.00'), currency=None); assert resolve_line_currency(line_with_currency, account, base_currency='SGD') == 'EUR'; assert resolve_line_currency(line_no_currency, account, base_currency='SGD') == 'USD'; account_no_currency = Account(name='Salary', type=AccountType.INCOME, currency=None); assert resolve_line_currency(line_no_currency, account_no_currency, base_currency='sgd') == 'SGD'
def test_AC5_32_4_fx_conversion_error_response_model_declared(): 'AC-reporting.income-typed.4 AC5.32.4'; err = FxConversionErrorResponse(detail='no FX rate for USD/SGD'); assert err.detail == 'no FX rate for USD/SGD'
def test_AC5_32_5_normalize_currency_code_is_shared_helper(): 'AC-reporting.income-typed.5 AC5.32.5'; assert normalize_currency_code('  sgd ') == 'SGD'; assert normalize_currency_code('usd') == 'USD'
async def test_AC5_32_6_endpoint_returns_normalized_currency_for_soft_base_config(client: AsyncClient, db: AsyncSession, test_user, monkeypatch: pytest.MonkeyPatch): 'AC-reporting.income-typed.6 AC5.32.6'; from src import config; monkeypatch.setattr(config.settings, 'base_currency', 'sgd'); salary = Account(user_id=test_user.id, name='Salary Income', type=AccountType.INCOME, currency='SGD'); cash = Account(user_id=test_user.id, name='Cash', type=AccountType.ASSET, currency='SGD'); db.add_all([salary, cash]); await db.flush(); entry = JournalEntry(user_id=test_user.id, entry_date=date(2026, 5, 1), memo='income', status=JournalEntryStatus.POSTED); db.add(entry); await db.flush(); db.add_all([JournalLine(journal_entry_id=entry.id, account_id=cash.id, direction=Direction.DEBIT, amount=Decimal('100.00'), currency='SGD'), JournalLine(journal_entry_id=entry.id, account_id=salary.id, direction=Direction.CREDIT, amount=Decimal('100.00'), currency='SGD')]); await db.commit(); response = await client.get('/income/annualized?as_of=2026-05-20'); assert response.status_code == 200; data = response.json(); assert data['currency'] == 'SGD'; assert data['annualized_salary'] == '100.00'; assert data['annualized_total'] == '100.00'
